                  <label uib-btn-checkbox ng-click="$ctrl.para_acudientes_toggle($ctrl.actividad.para_acudientes)" ng-model="$ctrl.actividad.para_acudientes" uib-tooltip="Actividad para los acudientes" tooltip-popup-delay="500" tooltip-append-to-body="true" class="btn btn-default shiny">Para acudientes</label>
