        <label ng-model="$ctrl.enfermeria.patol_bronquis" btn-checkbox-false="0" btn-checkbox-true="1" uib-btn-checkbox ng-click="$ctrl.guardarValorEnfermeria($ctrl.enfermeria, 'patol_bronquis', $ctrl.enfermeria.patol_bronquis)" class="btn btn-primary">Bronquitis</label>
