        <label ng-model="$ctrl.enfermeria.fami_diabetes" btn-checkbox-false="0" btn-checkbox-true="1" uib-btn-checkbox ng-click="$ctrl.guardarValorEnfermeria($ctrl.enfermeria, 'fami_diabetes', $ctrl.enfermeria.fami_diabetes)" class="btn btn-primary">Diabetes</label>
